# ctrl-shift.map: loaded on top of a layout of this directory: loadkeys -u LAYOUT ctrl-shift.
# Made by vendor/keymaps/regen_keymaps.sh; do not edit.
#
# Either Ctrl with either Shift, pressed in either order, switches to the
# other layout; the second key toggles ShiftL_Lock and does nothing else.
control keycode 42 = ShiftL_Lock
control keycode 54 = ShiftL_Lock
control shiftl keycode 42 = ShiftL_Lock
control shiftl keycode 54 = ShiftL_Lock
shift keycode 29 = ShiftL_Lock
shift keycode 97 = ShiftL_Lock
shift shiftl keycode 29 = ShiftL_Lock
shift shiftl keycode 97 = ShiftL_Lock
